// Sprint Fase 3 CAMADA 3 (15-17/08/2026) — API do juiz de módulo. FORA de
// /api/admin (painel admin do SaaS, auth separada + 404-obscurity): aqui é
// feature do dashboard normal, auth de usuário via getAuthContext.
//   GET  → { latest, history } (pro selo do dashboard + a tela /juiz)
//   POST → roda o juiz agora, persiste e devolve o relatório ("rodar agora")
// O cron chama o MESMO POST (dono único da execução).

import { NextRequest, NextResponse } from 'next/server'
import { prisma } from '@/lib/db'
import { getAuthContext } from '@/lib/auth/rbac'
import { handleApiError } from '@/lib/api/handle-error'
import { runModuleJudge } from '@/lib/loans/run-module-judge'
import { runAndPersistStockJudge } from '@/lib/stock/run-stock-judge'

// Estoque vive em tabela PRÓPRIA (stock_judge_report, isolado) — o selo agrega lendo-a.
async function ultimoStock() {
  const s = await prisma.stockJudgeReport.findFirst({ orderBy: { runAt: 'desc' } })
  return { stockIssues: s?.stockIssues ?? 0, stockDetail: s ? parseDetail(s.detail as unknown) : null, stockRunAt: s?.runAt ?? null }
}

// RESILIENTE (17/08) + AGNÓSTICO AO SCHEMA (String OU Json): 1 relatório com
// detail ruim NÃO pode derrubar o GET (era o que fazia o selo cair no cinza
// "nunca rodou"). Aceita string (parse), objeto (coluna Json/legado), ou default
// — nunca estoura. `as unknown` porque o tipo varia (dev SQLite String, e há
// linha legado como objeto).
function parseDetail(d: unknown): unknown {
  if (d && typeof d === 'object') return d
  if (typeof d === 'string') {
    try { return JSON.parse(d) } catch { /* detail corrompido — cai no default */ }
  }
  return { byCompany: [], sharedTx: [], balanceChecks: [], dupStableKey: [], vendaChecks: [], cardChecks: [], cardResumo: [] }
}

/**
 * ⛔ VAZAMENTO FECHADO (30/08/2026): este endpoint chamava `getAuthContext(request)` **sem
 * empresa** — ou seja, bastava estar LOGADO pra ler o relatório do juiz de TODAS as
 * empresas (invariantes de empréstimo, cartão, vendas e estoque, com valores). Uma
 * operadora de estoque recém-convidada lia tudo.
 *
 * ⚠️ Não dá pra usar `ctx.requirePermission` aqui: o relatório é GLOBAL (roda pra todas as
 * empresas), e `requirePermission` é escopado por empresa. Então a régua é: **a pessoa
 * precisa ter `transaction.view` em ALGUMA empresa** — quem cuida do financeiro em algum
 * lugar pode ler o selo; quem só opera estoque, não.
 */
async function podeVerOJuiz(userId: string): Promise<boolean> {
  const papeis = await prisma.userCompanyRole.findMany({
    where: { userId },
    include: { role: { include: { permissions: { include: { permission: true } } } } },
  })
  const chaves = papeis.flatMap((p) => p.role.permissions.map((rp) => rp.permission.key))
  return chaves.some((k) => k === 'transaction.view' || k === '*' || k === '*.view')
}

const NEGADO = NextResponse.json(
  { erro: 'Só quem tem acesso ao financeiro pode ver o relatório do juiz.', code: 'FORBIDDEN' },
  { status: 403 },
)

export async function GET(request: NextRequest) {
  try {
    const ctx = await getAuthContext(request)
    if (!(await podeVerOJuiz(ctx.user.id))) return NEGADO
    const rows = await prisma.loanModuleJudgeReport.findMany({ orderBy: { runAt: 'desc' }, take: 30 })
    const history = rows.map((r) => ({ ...r, detail: parseDetail(r.detail as unknown) }))
    const stock = await ultimoStock()
    const latest = history[0] ? { ...history[0], stockIssues: stock.stockIssues, stockDetail: stock.stockDetail } : null
    return NextResponse.json({ latest, history, stock })
  } catch (e) {
    return handleApiError(e)
  }
}

export async function POST(request: NextRequest) {
  try {
    const ctx = await getAuthContext(request)
    if (!(await podeVerOJuiz(ctx.user.id))) return NEGADO
    const [rep, stockRep] = await Promise.all([runModuleJudge(prisma), runAndPersistStockJudge(prisma)])
    const saved = await prisma.loanModuleJudgeReport.create({
      data: {
        passed: rep.passed,
        totalContracts: rep.totalContracts,
        totalFail: rep.totalFail,
        balanceIssues: rep.balanceIssues,
        dupIssues: rep.dupIssues,
        vendaIssues: rep.vendaIssues,
        cardIssues: rep.cardIssues,
        durationMs: rep.durationMs,
        detail: JSON.stringify({ byCompany: rep.byCompany, sharedTx: rep.sharedTx, balanceChecks: rep.balanceChecks, dupStableKey: rep.dupStableKey, vendaChecks: rep.vendaChecks, cardChecks: rep.cardChecks, cardResumo: rep.cardResumo }),
      },
    })
    return NextResponse.json({ ok: true, report: { ...saved, detail: parseDetail(saved.detail as unknown), stockIssues: stockRep.stockIssues }, stock: stockRep })
  } catch (e) {
    return handleApiError(e)
  }
}
