// ESTOQUE ↔ FINANCEIRO — invariantes da PONTE 1 (24/08).
//
// F1 (ERRO): toda conta a pagar com `origin='ESTOQUE_NF'` tem nota-mãe válida e valor
//   batendo com a duplicata. É o contrapeso da exceção de isolamento: o estoque ganhou
//   permissão de escrever no financeiro, então o juiz confere TODA linha que ele escreveu.
//   Sem isso, a ponte poderia inflar o contas a pagar (e o fluxo de caixa) em silêncio.
//
// F2 (ERRO): link apontando conta que não existe mais (alguém apagou a conta pelo
//   financeiro) — o rastro fica órfão e o dono acha que mandou algo que não está lá.
//
// F3 (AVISO): parcela conferida há mais de 7 dias e ainda não enviada pro contas a pagar —
//   boleto esquecido no estoque é boleto que vence sem aparecer no fluxo de caixa.
//   ⚠️ EXCLUI as "A DEFINIR" (sem data): elas são cobradas pelo F5, e o mesmo caso em dois
//   alarmes é como se ensina o dono a ignorar os dois.
// F5 (AVISO, 03/09): nota confirmada cuja parcela está SEM DATA de vencimento — "combinar o
//   vencimento com o fornecedor" é trabalho pendente, e é categoria PRÓPRIA: não é atraso
//   (não há data pra ter passado) nem esquecimento de envio.

import type { PrismaClient, Prisma } from '@prisma/client'
import type { StockInvariantFail } from './stock-invariants'
import { ORIGEM_PONTE } from './ponte-contas-pagar'

type Db = PrismaClient | Prisma.TransactionClient

export const F3_DIAS = 7
const CENTAVO = 0.01
const round2 = (n: number) => Math.round((n + 1e-9) * 100) / 100

export async function checkPonteInvariants(db: Db, now: Date = new Date()): Promise<StockInvariantFail[]> {
  const fails: StockInvariantFail[] = []

  // ---- F1: toda conta com a marca da ponte é rastreável e bate ----
  const contasDaPonte = await db.transaction.findMany({
    where: { origin: ORIGEM_PONTE },
    // ⚠️ conta a pagar NASCE SEM bankAccount (só ganha ao ser paga) — resolver a empresa
    // por ali devolvia null e o alerta se perdia no filtro por empresa. Vem pelo fornecedor.
    select: {
      id: true, amount: true, dueDate: true, description: true,
      supplier: { select: { companyId: true } },
      bankAccount: { select: { companyId: true } },
    },
  })
  if (contasDaPonte.length) {
    const links = await db.stockPayableLink.findMany({
      where: { transactionId: { in: contasDaPonte.map((c) => c.id) } },
    })
    const linkPorTx = new Map(links.map((l) => [l.transactionId, l]))

    for (const c of contasDaPonte) {
      const link = linkPorTx.get(c.id)
      if (!link) {
        // conta marcada como vinda do estoque, mas SEM amarra: ou a ponte gravou torto,
        // ou alguém marcou `origin` na mão. Nos dois casos o rastro não fecha.
        fails.push({ invariante: 'F1', companyId: c.supplier?.companyId ?? c.bankAccount?.companyId ?? null, detalhe: `conta a pagar "${c.description}" está marcada origem=${ORIGEM_PONTE} mas NÃO tem vínculo com nota/entrada do estoque — rastro quebrado.` })
        continue
      }
      if (Math.abs(round2(c.amount) - round2(link.valor)) > CENTAVO) {
        // ⚠️ o link guarda o valor do COMBINADO no momento do envio — que pode ser a
        // duplicata do XML ou a parcela renegociada. A frase não diz mais "a duplicata da
        // nota", porque desde 29/08 os dois podem legitimamente divergir.
        fails.push({ invariante: 'F1', companyId: link.companyId, detalhe: `conta ${c.id} vale R$ ${round2(c.amount).toFixed(2)} mas a parcela combinada diz R$ ${round2(link.valor).toFixed(2)} — a ponte inflaria o contas a pagar.` })
      }
      if (link.origem === 'NFE') {
        const nota = await db.stockNfe.findFirst({ where: { id: link.refId, companyId: link.companyId }, select: { id: true } })
        if (!nota) fails.push({ invariante: 'F1', companyId: link.companyId, detalhe: `conta ${c.id} aponta a nota ${link.refId}, que não existe — conta a pagar sem nota-mãe.` })
      } else {
        const ent = await db.stockEntradaManual.findFirst({ where: { id: link.refId, companyId: link.companyId }, select: { id: true } })
        if (!ent) fails.push({ invariante: 'F1', companyId: link.companyId, detalhe: `conta ${c.id} aponta a entrada manual ${link.refId}, que não existe.` })
      }
    }
  }

  // ---- F2: amarra órfã (a conta sumiu do financeiro) ----
  const todosLinks = await db.stockPayableLink.findMany({ select: { id: true, companyId: true, transactionId: true, valor: true } })
  if (todosLinks.length) {
    const existentes = new Set((await db.transaction.findMany({
      where: { id: { in: todosLinks.map((l) => l.transactionId) } }, select: { id: true },
    })).map((t) => t.id))
    for (const l of todosLinks) {
      if (!existentes.has(l.transactionId)) {
        fails.push({ invariante: 'F2', companyId: l.companyId, detalhe: `o estoque diz ter enviado R$ ${round2(l.valor).toFixed(2)} pro contas a pagar (conta ${l.transactionId}), mas essa conta não existe mais — apagada pelo financeiro?` })
      }
    }
  }

  // ---- F3 (aviso): boleto esquecido no estoque ----
  const limite = new Date(now.getTime() - F3_DIAS * 86_400_000)
  const sugestoes = await db.stockPayableSuggestion.findMany({
    where: { criadoEm: { lt: limite } },
    select: { id: true, companyId: true, supplierNome: true, valor: true, nfeId: true, nDup: true, dVenc: true },
  })
  if (sugestoes.length) {
    const enviadas = new Set((await db.stockPayableLink.findMany({
      where: { origem: 'NFE', suggestionId: { in: sugestoes.map((s) => s.id) } }, select: { suggestionId: true },
    })).map((l) => l.suggestionId))
    for (const s of sugestoes) {
      if (enviadas.has(s.id)) continue
      // ⛔ SEM DATA é assunto do F5, não do F3: o mesmo caso em dois alarmes ensina o dono a
      // ignorar os dois (a lição dos 111 alarmes falsos de venda).
      if (!s.dVenc) continue
      const venc = s.dVenc ? ` (vence ${s.dVenc.toISOString().slice(0, 10)})` : ''
      fails.push({ invariante: 'F3', companyId: s.companyId, nivel: 'aviso', detalhe: `boleto de "${s.supplierNome}" R$ ${round2(s.valor).toFixed(2)}${venc} está conferido há mais de ${F3_DIAS} dias e ainda NÃO foi pro contas a pagar — vence sem aparecer no fluxo de caixa.` })
    }
  }

  // ---- F4: o COMBINADO vigente fecha com o que o financeiro vai cobrar ----
  //
  // ⭐ MUDANÇA DE RÉGUA (29/08/2026 — caso BOX PAPER). Antes a amarra era contra as
  // duplicatas CRUAS do XML. Isso deixou de valer no dia em que renegociação virou um
  // caminho de primeira classe: a nota diz 3 parcelas, o combinado diz 4, e **os dois
  // estão certos**. Validar contra o XML acusaria toda renegociação legítima como erro —
  // e alarme falso repetido é como um alarme morre (a lição dos 111 alarmes de vendas).
  //
  // A régua nova: Σ das parcelas ATIVAS == Σ do que o financeiro tem pra essa nota
  // (contas criadas + sugestões ainda na fila). Se divergir, o combinado e o financeiro
  // discordam — que é o defeito real, independente do que a nota diz.
  const renegociadas = await db.stockParcelaCombinada.findMany({
    where: { ativo: true, origem: 'RENEGOCIADO', origemDoc: 'NFE' },
    select: { companyId: true, refId: true, numero: true, valor: true, motivo: true },
  })
  if (renegociadas.length) {
    const porNota = new Map<string, typeof renegociadas>()
    for (const r of renegociadas) {
      const k = `${r.companyId}|${r.refId}`
      const lista = porNota.get(k) ?? []
      lista.push(r)
      porNota.set(k, lista)
    }
    for (const [k, parcelas] of porNota) {
      const [companyId, refId] = k.split('|')
      const somaCombinado = round2(parcelas.reduce((s, p) => s + p.valor, 0))

      const linksDaNota = await db.stockPayableLink.findMany({
        where: { companyId, origem: 'NFE', refId }, select: { transactionId: true, valor: true, nDup: true },
      })
      const idsVivos = new Set(
        (await db.transaction.findMany({ where: { id: { in: linksDaNota.map((l) => l.transactionId) } }, select: { id: true } })).map((t) => t.id),
      )
      const enviadas = linksDaNota.filter((l) => idsVivos.has(l.transactionId))
      const numerosEnviados = new Set(enviadas.map((l) => l.nDup))
      const naFila = await db.stockPayableSuggestion.findMany({
        where: { companyId, nfeId: refId }, select: { nDup: true, valor: true },
      })
      const somaFinanceiro = round2(
        enviadas.reduce((s, l) => s + l.valor, 0) +
          naFila.filter((s2) => !numerosEnviados.has(s2.nDup)).reduce((s2, x) => s2 + x.valor, 0),
      )

      if (Math.abs(round2(somaCombinado - somaFinanceiro)) > CENTAVO) {
        fails.push({
          invariante: 'F4',
          companyId,
          detalhe:
            `o combinado da nota ${refId} soma R$ ${somaCombinado.toFixed(2)} em ${parcelas.length} parcela(s), ` +
            `mas o financeiro tem R$ ${somaFinanceiro.toFixed(2)} entre contas criadas e fila — ` +
            `o que foi acertado com o fornecedor e o que vai ser cobrado discordam.`,
        })
      }

      // ⚠️ AVISO, não erro: divergir da NOTA é legítimo (desconto/juros de renegociação).
      // O que o juiz cobra é que o PORQUÊ esteja escrito — número sem motivo vira mistério
      // pro contador daqui a três meses.
      const nota = await db.stockNfe.findFirst({ where: { id: refId, companyId }, select: { vNF: true } })
      const totalNota = round2(nota?.vNF ?? 0)
      if (totalNota > 0 && Math.abs(round2(somaCombinado - totalNota)) > CENTAVO && !parcelas.some((p) => p.motivo)) {
        fails.push({
          invariante: 'F4', companyId, nivel: 'aviso',
          detalhe: `a nota ${refId} vale R$ ${totalNota.toFixed(2)} e o combinado soma R$ ${somaCombinado.toFixed(2)}, sem motivo registrado — anote o porquê (desconto, juros da renegociação).`,
        })
      }
    }
  }

  // ---- F5 (aviso, 03/09): parcela SEM DATA — "combinar o vencimento" é trabalho pendente ----
  //
  // ⛔ ELE EXISTE PORQUE O F3 ERA CEGO PRA ISSO: nota sem boleto não gerava sugestão nenhuma,
  // e o F3 vigia sugestão parada — **sugestão que não nasce não pára**. Foi assim que
  // R$ 8.588,75 em 21 notas ficaram fora do fluxo de caixa sem nenhum alarme.
  //
  // ⚠️ CATEGORIA PRÓPRIA, nunca "atrasado": não há data pra ter passado. O texto diz o que
  // fazer — combinar a data — em vez de mandar procurar um atraso que não existe.
  const semData = await db.stockPayableSuggestion.findMany({
    where: { dVenc: null },
    select: { id: true, companyId: true, supplierNome: true, valor: true, chave: true },
  })
  if (semData.length) {
    const enviadasSemData = new Set((await db.stockPayableLink.findMany({
      where: { suggestionId: { in: semData.map((s) => s.id) } }, select: { suggestionId: true },
    })).map((l) => l.suggestionId))
    const porEmpresa = new Map<string, { n: number; total: number }>()
    for (const s of semData) {
      if (enviadasSemData.has(s.id)) continue
      const a = porEmpresa.get(s.companyId) ?? { n: 0, total: 0 }
      a.n++; a.total = round2(a.total + s.valor)
      porEmpresa.set(s.companyId, a)
    }
    for (const [companyId, a] of porEmpresa) {
      fails.push({
        invariante: 'F5', companyId, nivel: 'aviso',
        detalhe: `${a.n} nota(s) sem data de pagamento (R$ ${a.total.toFixed(2)}) — combine o vencimento com o fornecedor e defina a data. `
          + 'Sem data elas não viram conta a pagar e não aparecem no fluxo de caixa.',
      })
    }
  }

  return fails
}
